# pillar1_translations_part3.py - Handcrafted translations for DatingLandmarkEvent items

TRANSLATIONS_LANDMARK = {
    "DatingLandmarkEvent.1401.1": "Cỗ xe ngựa lăn bánh rẽ về hướng đông tiến vào Học Viện, những dãy lầu tráng lệ lướt qua trên đỉnh đầu. \"Oa—\" Bạn khẽ tựa người vào cánh cổng phía trước.",
    "DatingLandmarkEvent.1401.2": "Bạn nghe thấy tiếng gót giày của ==DATING_CHARACTER== khẽ gõ lách cách trên nền đá. Nàng đứng nép bên cột biển chỉ dẫn, một tay khẽ đặt hờ lên thành lan can.",
    "DatingLandmarkEvent.1401.3": "Khi cỗ xe chầm chậm lăn bánh rời đi, một làn gió nhẹ mơn man thổi qua tà áo và nàng khẽ mỉm cười vẫy tay chào tạm biệt bạn.",

    "DatingLandmarkEvent.1801.1": "Khu phố đông đúc người qua kẻ lại tấp nập. Bạn len qua dòng người, mắt không ngừng dõi tìm bóng hình Alina.",
    "DatingLandmarkEvent.1801.2": "Một chuyển động bất chợt bên khóe mắt thu hút sự chú ý của bạn. Ngoảnh đầu lại, bạn thấy Alina đang ngồi đung đưa đôi chân trên bờ tường gạch thấp ngay bên cạnh.",
    "DatingLandmarkEvent.1801.3": "\"Cuối cùng cậu cũng để ý thấy rồi nha!\" Cô nàng nhảy tót xuống đất, toe toét cười. \"Tớ cứ tưởng cậu lại định bước vụt qua mặt tớ thêm lần nữa chứ!\"",

    "DatingLandmarkEvent.1802.1": "Thời tiết hôm nay tuyệt đẹp, nhuộm phố phường Filanis rực rỡ như một bức tranh sơn dầu. Dưới ánh nắng vàng rực rỡ, dòng người trong tà áo lam trắng dập dìu qua lại tựa như một dòng sông sống động.",
    "DatingLandmarkEvent.1802.2": "Alina tự nhiên khoác nhẹ tay bạn, cả hai thong thả rảo bước dọc theo con phố chẳng màng đích đến.",
    "DatingLandmarkEvent.1802.3": "Alina dẫn bạn lên một gò đất cao thoáng đãng. Từ nơi đây, bạn có thể phóng tầm mắt ôm trọn toàn cảnh phố thị, rặng cây xanh rì ngoài rìa thành phố, và mặt hồ lấp lánh phản chiếu ánh dương nơi vài cánh buồm trắng đang lững lờ trôi.",

    "DatingLandmarkEvent.1803.1": "Bạn rẽ vào một con hẻm nhỏ lát đá cuội gồ ghề. Nghe đồn nơi này từng là một trạm gác tiền tiêu từng trải qua biết bao trận giao tranh khốc liệt.",
    "DatingLandmarkEvent.1803.2": "Thế nhưng giờ đây, cỏ dại mọc um tùm rủ xuống từ những mái ngói rêu phong, lớp vữa tróc lở khỏi tường, để lộ những viên gạch nứt toác vết hằn năm tháng.",
    "DatingLandmarkEvent.1803.3": "Vài phút sau, bạn bước ra khỏi con hẻm hoang vắng để trở lại trục đường chính, đón chào bạn là tiếng đàn lute du dương êm ả cùng hương trầm thơm ngát vấn vương.",

    "DatingLandmarkEvent.1804.1": "Dưới mái vòm của nhà hát, một thương nhân đang bày bán những chú thú nhồi bông đáng yêu. Bạn bước lại gần, ngắm nhìn mớ đồ chơi rồi hỏi: \"Ở đây có gấu bông không chú?\"",
    "DatingLandmarkEvent.1804.2": "Người bán hàng lục lọi trong thùng rồi lôi ra một chú gấu đưa cho bạn. Bạn khẽ bóp thử rồi hỏi: \"Chú có thể nhuộm chú gấu này thành màu hồng được không ạ?\"",
    "DatingLandmarkEvent.1804.3": "Ngẫm nghĩ một thoáng, bạn ngắt một cọng cỏ dưới chân rồi cắm vào khóe miệng chú gấu. \"Hoàn hảo! Cứ như thế này này. Cháu muốn đặt làm riêng một chú gấu y hệt thế này cơ!\"",

    "DatingLandmarkEvent.1805.1": "Bạn mua hai phần lê chưng mật ong thơm phức từ quầy đồ ăn vặt. Bạn há miệng ngoạm sạch phần của mình chỉ trong một nốt nhạc, và trước khi kịp cảm nhận hết vị ngọt, mắt bạn đã dán chặt vào quả lê trên tay Alina.",
    "DatingLandmarkEvent.1805.2": "\"Cho tớ cắn một miếng với được không?\"\n\"Ơ kìa... tớ vừa cắn rồi mà, dính mật dính tay lem nhem hết rồi nè...\"\n\"Không sao hết, tớ chẳng ngại đâu!\" Thế là bạn đã dỗ ngọt thành công nửa quả lê thơm ngon từ tay cô nàng.",
    "DatingLandmarkEvent.1805.3": "Một suy nghĩ tinh quái chợt lóe lên, bạn quay sang nhìn cô nàng với vẻ mặt nghiêm túc không tưởng: \"Sau này nếu cậu thấy món đồ ngọt nào không có mật ong, tuyệt đối chớ có ăn nha!\"\n\"Cậu nói lăng nhăng gì đó... Lại tính lừa nốt nửa quả lê còn lại của tớ chứ gì!\"",

    "DatingLandmarkEvent.1806.1": "Hoàng hôn buông xuống, dát một lớp ánh vàng óng ả lên những con đường lát đá cuội. Từng bước chân hai bạn khẽ gõ nhịp đều đặn trên nền gạch như một khúc nhạc êm đềm xa xăm.",
    "DatingLandmarkEvent.1806.2": "Những lời thủ thỉ dịu dàng từ ban công các ngôi nhà khẽ bay bổng trong gió, hòa cùng tiếng chuyện trò thưa thớt nơi công viên. Mặt trời lặn dần về tây, cả thế gian dường như lắng lại trong tĩnh lặng.",
    "DatingLandmarkEvent.1806.3": "Người thợ thắp đèn bắc thang châm sáng từng ngọn đèn đường, trong khi bạn và Alina nép sát bên nhau ấm áp. Bạn khẽ khép hờ mắt, mặc cho thời gian cứ thế êm đềm trôi qua từng giây.",

    "DatingLandmarkEvent.1901.1": "Bạn đứng tựa lưng vào gốc cây cổ thụ, kiên nhẫn đợi Alina tới.",
    "DatingLandmarkEvent.1901.2": "Một bóng hình quen thuộc chợt xuất hiện nơi góc phố, đang bồn chồn ngó nghiêng tứ phía. Một cơn gió thổi tới như khẽ đẩy bạn bước ra khỏi đám đông, và cô nàng lập tức nhận ra bạn ngay.",
    "DatingLandmarkEvent.1901.3": "Alina nở nụ cười rạng rỡ, chân sáo bước nhanh về phía bạn, trong tay còn cầm theo hai túi đồ nhỏ xinh.",

    "DatingLandmarkEvent.1902.1": "Ngâm mình thư thả trong làn nước suối khoáng ấm áp, bạn ngắm nhìn những áng mây trắng lững lờ trôi qua khung cửa kính trên trần. Bóng râm phủ mờ sườn đồi phía xa xăm, biến ảo kỳ ảo dưới làn nắng thu.",
    "DatingLandmarkEvent.1902.2": "Bạn khẽ nhắm mắt. Gió núi vi vu thổi qua từng vòm cây xào xạc. Khi tiếng gió ngưng bặt, một sự tĩnh lặng sâu lắng bao trùm lấy tâm hồn tựa cơn mưa mùa thu mát lành.",
    "DatingLandmarkEvent.1902.3": "\"Cậu thích ngắm bầu trời thế cơ à? Trên đó có gì hay ho sao?\"\n\"Chẳng có gì cả.\"\n\"Thế thì ngắm làm chi cho mất công?\"\n\"Alina à, cuộc đời này tươi đẹp chính là vì nó chẳng cần bất kỳ lý do hay mục đích nào cả.\"",

    "DatingLandmarkEvent.1903.1": "Khi chiếc khay hoa quả nổi bồng bềnh lướt qua mặt nước, bạn tiện tay nhón lấy vài miếng. Vừa há miệng định thưởng thức thì Alina đã tinh nghịch té một vốc nước ấm thẳng vào mặt bạn.",
    "DatingLandmarkEvent.1903.2": "Khung cảnh này mang lại cảm giác thân thuộc đến kỳ lạ, tựa như một ký ức từng diễn ra ở khu nghỉ dưỡng nào đó trong quá khứ. Một lần nữa, bạn thầm tự hỏi rốt cuộc bản thân mình là ai.",
    "DatingLandmarkEvent.1903.3": "Nếu bạn đang hiện hữu nơi đây, bạn không thể là một ai khác. Bạn không muốn thân phận của mình mãi mơ hồ như sương khói.\n\"Nè... Cậu giận tớ thật đấy à?\" Alina lo lắng khẽ hỏi.",

    "DatingLandmarkEvent.1904.1": "Bạn kể cho Alina nghe về quá khứ của mình. Về núi non trùng điệp và biển cả bao la, về tuyết trắng mùa đông và hoa nở ngày xuân, về từng rặng san hô rực rỡ và những bãi cát trải dài bất tận...",
    "DatingLandmarkEvent.1904.2": "Những điều bạn kể vừa kỳ ảo lại vừa sống động lạ thường, cuốn hút đến mức Alina hoàn toàn chìm đắm vào từng câu chữ. Cô nàng say sưa lắng nghe, hai mắt long lanh như những vì sao.",
    "DatingLandmarkEvent.1904.3": "\"Đó quả là một câu chuyện đẹp...\" Alina khẽ chớp mắt, khóe môi vương nét cười dịu dàng. \"Tớ cũng ước gì một ngày nào đó được cùng cậu chu du khắp những chân trời ấy.\"",

    "DatingLandmarkEvent.1905.1": "Mặt trời khuất dần sau rặng núi, để lại một khoảng trời nhuốm sắc hồng phấn ngọt ngào. Alina bưng ra một bình trà nóng thơm ngát.",
    "DatingLandmarkEvent.1905.2": "\"Trà này thơm mùi đào quá nè!\"\nBạn nhấc nắp ấm lên tò mò nhìn vào bên trong. Rõ ràng chỉ là búp trà khô bình thường, vậy mà khi nhấp một ngụm, vị ngọt thanh tựa đào chín lại lan tỏa khắp đầu lưỡi.",
    "DatingLandmarkEvent.1905.3": "\"Bí quyết nằm ở tâm trạng của người pha đấy,\" Alina mỉm cười đắc ý, tự rót cho mình một chén đầy.",

    "DatingLandmarkEvent.1906.1": "Trời đã về khuya, vầng trăng khuyết lơ lửng trên nền trời tím biếc mộng mơ. Bạn và Alina cùng tựa lưng vào ghế dài nghỉ ngơi, lặng nhìn những tia sáng cuối ngày dần tan biến.",
    "DatingLandmarkEvent.1906.2": "\"Mỗi khi thấy cô đơn, cậu cứ nhìn lên mặt trăng nhé,\" Alina khẽ nghiêng đầu nói với bạn. \"Dù thời gian có trôi qua bao lâu đi nữa, vầng trăng vẫn mãi vẹn nguyên. Chỉ cần cùng ngước nhìn lên, chúng mình sẽ luôn ngắm chung một ánh trăng.\"",
    "DatingLandmarkEvent.1906.3": "Hai người rủ rỉ trò chuyện không dứt dưới ánh trăng bàng bạc cho tới khi đêm đen hoàn toàn buông xuống. Bạn khẽ giơ tay lên không trung, như thể muốn nắm trọn ánh trăng vào lòng bàn tay.",

    "DatingLandmarkEvent.2001.1": "Alina đang đứng đợi bạn trên những bậc thềm đá. Ngọn gió ban mai khẽ vờn qua, thổi tung lọn tóc sau gáy và làm tấm khăn choàng của nàng tung bay phần phật tựa như lá cờ.",
    "DatingLandmarkEvent.2001.2": "Cơn mưa ban nãy vừa dứt. Từng giọt nước mưa còn đọng lại trên mái hiên tí tách rơi xuống, bắt lấy ánh ban mai lấp lánh như những hạt pha lê.",
    "DatingLandmarkEvent.2001.3": "\"Cậu bắt tớ đợi dài cả cổ rồi đó nha!\" Alina cười phụng phịu rồi kéo tay bạn bước vào trong nhà.",

    "DatingLandmarkEvent.2002.1": "Trong phòng lạnh buốt giá, chóp mũi bạn cũng dần tê cóng. Một vạt nắng mỏng manh hắt qua song cửa rọi lên vách tường. Nhận thấy bạn đang co ro vì lạnh, Alina liền ngồi xổm bên lò sưởi nhóm lửa lên.",
    "DatingLandmarkEvent.2002.2": "Gian phòng cuối cùng cũng ấm sực. Bạn ghé sát lại gần bếp lửa, để luồng hơi ấm phả nhẹ vào mặt.\n\"Coi chừng lấm lem hết mặt mũi bây giờ!\" Alina vội kéo bạn lùi lại. \"Mặt dính đầy muội than như mèo hen cho xem.\"",
    "DatingLandmarkEvent.2002.3": "Nàng khẽ hà hơi ấm vào lòng bàn tay rồi nhẹ nhàng áp lên hai má bạn. \"Mặt cậu lạnh ngắt như cục băng rồi này!\" nàng khẽ thốt lên.\nBàn tay nàng ấm áp tựa vầng hào quang rực rỡ, kéo bạn chìm đắm vào một buổi chiều mùa hạ êm đềm hoàn mỹ.",

    "DatingLandmarkEvent.2003.1": "Bạn và Alina ngồi bên chiếc bàn nhỏ cùng nhau nhâm nhi tách trà nóng trong khi củi lửa tí tách reo vui. Bất chợt, cả hai cùng cảm nhận được ánh nhìn của nhau và ánh mắt chạm nhau trong một khoảnh khắc ngưng đọng.",
    "DatingLandmarkEvent.2003.2": "Bạn cảm thấy hình bóng mình như thu nhỏ lại, in sâu trong đôi mắt long lanh sáng ngời của cô gái ấy. Có lẽ trong ánh mắt nàng, luôn có một vị trí đặc biệt được dành riêng cho bạn.",
    "DatingLandmarkEvent.2003.3": "Thoáng chút ngượng ngùng e ấp, nàng khẽ quay đầu về phía cửa sổ tránh đi ánh nhìn. Đôi tay búp măng ôm chặt tách trà, Alina khẽ thở dài một làn hơi ấm. Hơi thở mong manh chạm vào khung kính trắng muốt, phủ lên đó một lớp sương mờ ảo.",

    "DatingLandmarkEvent.2004.1": "\"Nhìn kìa, trời lại đổ mưa rồi,\" Alina nói, ánh mắt dõi nhìn ra ngoài ô cửa sổ.\nKhoảnh khắc này thật đáng để lưu giữ. Bạn kéo tay nàng lại gần khung cửa sổ rồi giơ chiếc điện thoại lên.",
    "DatingLandmarkEvent.2004.2": "Hai người quay lưng về phía cửa sổ, lấy hậu cảnh là bầu trời xám tro và vùng hoang vu đẫm nước mưa. Thế nhưng nền trời quá chói khiến gương mặt cả hai bị sẫm bóng. Bạn chỉnh lại tiêu cự, nhưng bầu trời bên ngoài lại cháy sáng trắng xóa.",
    "DatingLandmarkEvent.2004.3": "Bỏ cuộc với việc căn chỉnh ánh sáng, bạn bèn quay người đối diện thẳng với cửa kính. Tiếng màn trập vang lên tách một tiếng. Bạn cười hơi ngượng nghịu, còn cô nàng thì cười tươi rói đến tận mang tai. Nhìn bức ảnh, bạn thầm nghĩ: Mai này dù có ra sao, chỉ cần nhìn thấy nụ cười này, nhất định ta sẽ nhận ra nhau ngay tức khắc.",

    "DatingLandmarkEvent.2005.1": "Chẳng mấy chốc, ngoài trời mưa đã đổ xối xả. Bạn ngồi bên khung cửa sổ cùng Alina. Vùng hoang dã đẫm nước mưa, và cả thế gian xung quanh căn nhà gỗ bỗng trở nên tĩnh lặng đến lạ kỳ.",
    "DatingLandmarkEvent.2005.2": "Hòa vào bầu không khí lắng đọng, bạn rút điện thoại ra bật một bài nhạc êm dịu.\nCả hai cùng yên lặng lắng nghe. Ngay cả trong căn phòng kín gió này, hàng mi dài cong vút của nàng cũng khẽ run rẩy rung rinh.",
    "DatingLandmarkEvent.2005.3": "Khi tiếng trống nhịp nhàng cất lên, bạn đứng dậy và dịu dàng chìa tay về phía nàng. Alina đón lấy. Từng bước chân hai bạn đan xen, gõ nhịp rộn ràng trên sàn gỗ. Trong khoảnh khắc hoàn mỹ thế này, một giai điệu hay và một điệu khiêu vũ ngọt ngào chính là dấu ấn tuyệt vời nhất khắc ghi vào tương lai.",

    "DatingLandmarkEvent.2006.1": "Bạn tỉnh giấc khi màn đêm vừa tàn. Cơn mưa ngoài hiên đã dứt hẳn. Alina đang nằm ngủ say sưa bên cạnh bạn, nhịp thở đều đặn êm đềm. Giá như đêm nay có thể kéo dài vô tận, giá như cứ được nằm trên chiếc giường này mãi chẳng bao giờ phải thức dậy. Thế nhưng tia nắng ban mai vẫn xuyên qua khung cửa sổ rọi vào, chẳng chút nể nang.",
    "DatingLandmarkEvent.2006.2": "Alina cũng cựa mình tỉnh giấc ngay sau đó, đôi mắt ngái ngủ mơ màng ôm chầm lấy bạn. Nếu là một nhà thơ, có lẽ bạn sẽ tìm được những vần thơ hoàn mỹ nhất để diễn tả trọn vẹn cảm giác ấm áp và bình yên lúc này.",
    "DatingLandmarkEvent.2006.3": "Buổi sớm mai bừng sáng lung linh. Hai người cùng nhau chia sẻ bát cháo nóng thơm ngon. Lúc bạn chuẩn bị lên đường, nàng cẩn thận quàng chiếc khăn ấm quanh cổ bạn.\n\"Nhớ sớm về thăm em đấy nhé,\" nàng tiễn bạn ra tận cửa, còn không quên âu yếm xoa nhẹ vành tai bạn.",
}
